import pyomo.environ as pyo

DATA = {
    "areas": ["W", "T", "R"],
    "unit_cost": {"W": 3, "T": 2, "R": 4},
    "min_W_plus_T": 500,
    "max_W_minus_R": 2000,
    "exact_W_plus_R": 3000,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.A = pyo.Set(initialize=d["areas"])

    def var_bounds(m, a):
        if a == "W":
            return (0, d["exact_W_plus_R"])
        if a == "R":
            return (0, d["exact_W_plus_R"])
        return (0, None)

    model.x = pyo.Var(
        model.A,
        within=pyo.NonNegativeIntegers,
        bounds=var_bounds,
    )

    model.obj = pyo.Objective(
        expr=sum(d["unit_cost"][a] * model.x[a] for a in model.A),
        sense=pyo.minimize,
    )

    def c_W_plus_T_min(m):
        return m.x["W"] + m.x["T"] >= d["min_W_plus_T"]

    model.c_W_plus_T_min = pyo.Constraint(rule=c_W_plus_T_min)

    def c_W_minus_R_max(m):
        return m.x["W"] - m.x["R"] <= d["max_W_minus_R"]

    model.c_W_minus_R_max = pyo.Constraint(rule=c_W_minus_R_max)

    def c_W_plus_R_eq(m):
        return m.x["W"] + m.x["R"] == d["exact_W_plus_R"]

    model.c_W_plus_R_eq = pyo.Constraint(rule=c_W_plus_R_eq)

    return model
